const fs = require("fs");
const path = require("path");

const stamp = new Date().toISOString().replace(/[:.]/g, "-");

function backup(file) {
  if (fs.existsSync(file)) {
    fs.copyFileSync(file, `${file}.backup-ajustes-${stamp}`);
  }
}

function writeBase64(file, b64) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  backup(file);
  fs.writeFileSync(file, Buffer.from(b64, "base64").toString("utf8"), "utf8");
  console.log(`Atualizado: ${file}`);
}

const payloads = {
  "src/app/terapia/admin/clientes/page.tsx": "",
  "src/app/api/terapia/admin/clientes/route.ts": "",
  "src/app/api/terapia/admin/clientes/buscar/route.ts": ""
};
for (const [file, b64] of Object.entries(payloads)) {
  writeBase64(file, b64);
}

const portalFile = "src/app/terapia/acesso/[token]/page.tsx";
if (!fs.existsSync(portalFile)) {
  throw new Error(`Arquivo não encontrado: ${portalFile}`);
}
backup(portalFile);

let portal = fs.readFileSync(portalFile, "utf8");

// 1) Logo real no lugar do círculo TE
const logoRegex = /<div className="flex h-12 w-12 items-center justify-center rounded-full bg-\[#8AA27A\] font-black text-white shadow">\s*TE\s*<\/div>/;
if (logoRegex.test(portal)) {
  portal = portal.replace(
    logoRegex,
    `<img
                src="/terapia-icon-192-v2.png"
                alt="Terapia em Dia"
                className="h-12 w-12 rounded-full object-cover shadow"
              />`
  );
  console.log("Logo real aplicado no portal.");
} else if (!portal.includes('src="/terapia-icon-192-v2.png"')) {
  console.log("Aviso: não encontrei o círculo TE para substituir.");
}

// 2) Estado para recolher/expandir Minha Jornada
if (!portal.includes("const [jornadaAberta, setJornadaAberta]")) {
  const stateMarker = `  const [mesJornadaAberto, setMesJornadaAberto] =
    useState<string | null>(null);
`;
  if (!portal.includes(stateMarker)) {
    throw new Error("Não encontrei o estado mesJornadaAberto no portal.");
  }
  portal = portal.replace(
    stateMarker,
    stateMarker + `
  const [jornadaAberta, setJornadaAberta] =
    useState(false);
`
  );
}

// 3) Substituir somente o card Minha Jornada, preservando o restante do portal
const tituloJornada = portal.indexOf("Minha Jornada");
if (tituloJornada < 0) {
  throw new Error("Não encontrei Minha Jornada no portal.");
}

const marcadorCardJornada =
  '<div className="rounded-3xl border border-[#DCCFB8] bg-white p-6 shadow-lg md:col-span-2">';
const inicioJornada = portal.lastIndexOf(
  marcadorCardJornada,
  tituloJornada
);

const tituloAgenda = portal.indexOf(
  "Minha Agenda",
  tituloJornada
);

if (inicioJornada < 0 || tituloAgenda < 0) {
  throw new Error("Não consegui localizar os limites do card Minha Jornada.");
}

const marcadorCardAgenda =
  '<div className="rounded-3xl border border-[#DCCFB8] bg-white p-6 shadow-lg">';
const inicioAgenda = portal.lastIndexOf(
  marcadorCardAgenda,
  tituloAgenda
);

if (inicioAgenda < 0 || inicioAgenda <= inicioJornada) {
  throw new Error("Não consegui localizar o início do card Minha Agenda.");
}

const journeyBlock = Buffer.from("", "base64").toString("utf8");

portal =
  portal.slice(0, inicioJornada) +
  journeyBlock +
  portal.slice(inicioAgenda);

fs.writeFileSync(portalFile, portal, "utf8");
console.log("Minha Jornada agora abre e fecha por seta.");

console.log("");
console.log("AJUSTES APLICADOS.");
console.log("- Logo real do Terapia em Dia");
console.log("- Minha Jornada recolhível");
console.log("- Busca primeiro em club_clients");
console.log("- Adicionar paciente sem duplicar cadastro");
console.log("");
console.log("Agora rode npm run build.");
